syntax = "proto3";

package shop.v1;

import "google/protobuf/timestamp.proto";
option java_package = "com.example.shop";

// An item for sale.
message Item {
  string name = 1;
  double price = 2 [deprecated = true];
  repeated string tags = 3;
  map<string, int32> counts = 4;
  oneof kind {
    Physical physical = 5;
    Digital digital = 6;
  }
  reserved 7, 8 to 0x10;
  enum Status { STATUS_UNSPECIFIED = 0; ACTIVE = 1; }
  google.protobuf.Timestamp created = 9;
}

/* block
   comment */
service Shop {
  rpc GetItem(GetItemRequest) returns (Item) {}
  rpc Watch(stream Item) returns (stream Item);
}

message Item {
  option deprecated = true;
  reserved 7, 8 to 10, 15 to max;
  reserved "foo", "bar";
  optional string name = 1 [json_name = "n", (custom) = 1];
  required int32 id = 2;
  repeated string tags = 3 [packed = true];
  map<string, int32> counts = 4;
  oneof kind { Physical physical = 5; Digital digital = 6; }
  enum Status { option allow_alias = true; STATUS_UNSPECIFIED = 0; ACTIVE = 1; ALIVE = 1; }
  message Nested { bool ok = 1; bytes raw = 2; double d = 3; float f = 4; int64 i64 = 5; uint32 u = 6; uint64 u64 = 7; sint32 s = 8; sint64 s64 = 9; fixed32 f32 = 10; fixed64 f64 = 11; sfixed32 sf = 12; sfixed64 sf64 = 13; }
  google.protobuf.Timestamp created = 9;
  .shop.v1.Other other = 10;
  extensions 100 to 199;
  group Result = 11 { optional string url = 12; }
  Nested nested = 14;
}
extend Item { optional int32 extra = 100; }
service Shop {
  rpc GetItem(GetItemRequest) returns (Item);
  rpc Watch(stream Item) returns (stream Item);
}

